function [u, j] = whole_second_epoch(jd)
%WHOLE_SECOND_EPOCH  The UTC calendar date [Y M D h m s] of a Julian date with its seconds rounded to the whole second (half away from
%   zero), and that date's Julian date.
%   jd: real[1] (passed a plain number)
%   returns u: real[1][6] (passed a plain number)
%   returns j: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    u = zeros(6, 1);
    j = 0;
    u = asils.models.caltime.utc_of_jd(jd);
    u(6) = round(u(6));
    j = asils.models.caltime.jd_utc(u);
end
